import { getAuthenticatedUser, createClient } from '@/lib/supabase/server'
import { authedRatelimit } from '@/lib/rate-limit'
import { logger } from '@/lib/logger'
import { getTodayBookings } from '@/lib/today/queries'
import type { TodayBooking } from '@/lib/today/queries'

export type { TodayBooking }

export async function GET(request: Request) {
  const auth = await getAuthenticatedUser()
  if (!auth) {
    return Response.json({ error: 'Unauthorized' }, { status: 401 })
  }

  const { success } = await authedRatelimit.limit(auth.user.authId)
  if (!success) {
    return new Response('Too many requests', { status: 429, headers: { 'Retry-After': '60' } })
  }

  const { studioId } = auth
  const url = new URL(request.url)
  const artistId = url.searchParams.get('artistId') ?? undefined

  try {
    const supabase = await createClient()
    const bookings = await getTodayBookings(supabase, studioId, { artistId })
    logger.info({ studioId, artistId, count: bookings.length }, 'today.queue.fetched')
    return Response.json(bookings)
  } catch (err) {
    logger.error({ err, studioId }, 'today.queue.error')
    return Response.json({ error: 'Failed to fetch queue' }, { status: 500 })
  }
}

'use client'

import { useQuery } from '@tanstack/react-query'
import type { TodayBooking } from '@/app/api/today/queue/route'

export type { TodayBooking }

async function fetchTodayQueue(artistId?: string): Promise<TodayBooking[]> {
  const params = artistId ? `?artistId=${encodeURIComponent(artistId)}` : ''
  const res = await fetch(`/api/today/queue${params}`)
  if (!res.ok) throw new Error('Failed to fetch today queue')
  return res.json() as Promise<TodayBooking[]>
}

export function useTodayQueue(enabled: boolean, artistId?: string) {
  return useQuery({
    queryKey: ['today', 'queue', artistId],
    queryFn: () => fetchTodayQueue(artistId),
    enabled,
    staleTime: 60_000,
    refetchInterval: 60_000,
    retry: 1,
    placeholderData: [] as TodayBooking[],
  })
}

'use client'

import { CheckCircle2, AlertCircle, Clock, AlertTriangle } from 'lucide-react'
import { cn } from '@/lib/utils'

export type ChipState = 'done' | 'warning' | 'pending' | 'overdue'

interface StatusChipProps {
  label: string
  state: ChipState
  onClick?: () => void
  /** Emphasize this chip with a primary-color border (receptionist check-in mode) */
  emphasized?: boolean
}

const CONFIG: Record<
  ChipState,
  {
    icon: typeof CheckCircle2
    className: string
    ariaDescription: string
  }
> = {
  done: {
    icon: CheckCircle2,
    className:
      'bg-[var(--color-success-bg)] text-[var(--color-success-foreground)] border-[var(--color-success)]/30',
    ariaDescription: 'complete',
  },
  warning: {
    icon: AlertCircle,
    className:
      'bg-[var(--color-warning-bg)] text-[var(--color-warning-foreground)] border-[var(--color-warning)]/30',
    ariaDescription: 'needs attention',
  },
  pending: {
    icon: Clock,
    className:
      'bg-[var(--color-muted)] text-[var(--color-muted-foreground)] border-[var(--color-border)]',
    ariaDescription: 'pending',
  },
  overdue: {
    icon: AlertTriangle,
    className:
      'bg-[var(--color-destructive)]/10 text-[var(--color-destructive)] border-[var(--color-destructive)]/30',
    ariaDescription: 'overdue',
  },
}

export function StatusChip({ label, state, onClick, emphasized }: StatusChipProps) {
  const { icon: Icon, className, ariaDescription } = CONFIG[state]

  const baseClasses = cn(
    'inline-flex items-center gap-1 rounded-full border px-2 py-0.5 text-[10px] font-medium leading-none transition-all select-none',
    className,
    emphasized && 'border-[var(--color-primary)] shadow-[0_0_0_1px_var(--color-primary)]',
    onClick
      ? 'cursor-pointer hover:brightness-95 active:scale-95 focus-visible:outline-none focus-visible:ring-2 focus-visible:ring-[var(--color-ring)] focus-visible:ring-offset-1'
      : 'cursor-default',
  )

  const ariaLabel = `${label}: ${ariaDescription}${onClick ? ', click to act' : ''}`

  if (onClick) {
    return (
      <button
        type="button"
        className={baseClasses}
        onClick={onClick}
        aria-label={ariaLabel}
      >
        <Icon className="h-2.5 w-2.5 shrink-0" aria-hidden="true" />
        <span>{label}</span>
      </button>
    )
  }

  return (
    <span className={baseClasses} aria-label={ariaLabel}>
      <Icon className="h-2.5 w-2.5 shrink-0" aria-hidden="true" />
      <span>{label}</span>
    </span>
  )
}

'use client'

import { useState, useRef } from 'react'
import { format } from 'date-fns'
import { toast } from 'sonner'
import { Skeleton } from '@/components/ui/skeleton'
import { StatusChip } from './StatusChip'
import type { ChipState } from './StatusChip'
import { AppointmentDetailDrawer } from '@/components/appointments/AppointmentDetailDrawer'
import { cn } from '@/lib/utils'
import type { TodayBooking } from '@/hooks/use-today-queue'

interface TodayQueueProps {
  bookings: TodayBooking[]
  isLoading: boolean
  /** When true, check-in chip gets emphasized border (receptionist mode) */
  emphasizeCheckin?: boolean
  onRefresh?: () => void
}

function getCheckinState(booking: TodayBooking): ChipState {
  if (booking.status === 'in_progress' || booking.status === 'completed') return 'done'
  if (booking.status === 'confirmed') return 'pending'
  return 'pending'
}

function getFormsState(booking: TodayBooking): ChipState {
  if (!booking.hasRequiredForms) return 'done'
  if (booking.hasFormsSigned) return 'done'
  // Overdue if appointment is in the past
  const apptTime = new Date(booking.scheduled_at)
  if (apptTime < new Date()) return 'overdue'
  return 'warning'
}

function getDepositState(booking: TodayBooking): ChipState {
  if (!booking.deposit_cents) return 'done'
  if (booking.deposit_paid) return 'done'
  const apptTime = new Date(booking.scheduled_at)
  if (apptTime < new Date()) return 'overdue'
  return 'warning'
}

function getBalanceState(booking: TodayBooking): ChipState {
  if (booking.balanceRemaining <= 0) return 'done'
  if (booking.status === 'completed') return 'overdue'
  return 'pending'
}

function truncate(str: string, maxLen: number): string {
  if (str.length <= maxLen) return str
  return str.slice(0, maxLen - 1) + '…'
}

function QueueCardSkeleton() {
  return (
    <div
      className="shrink-0 scroll-snap-start rounded-xl border border-[var(--color-border)] bg-[var(--color-card)] p-3"
      style={{ width: 260, minHeight: 110 }}
      aria-hidden="true"
    >
      <div className="flex items-start gap-2">
        <Skeleton className="h-8 w-8 shrink-0 rounded-full" />
        <div className="flex-1 space-y-1.5">
          <Skeleton className="h-3.5 w-24" />
          <Skeleton className="h-3 w-32" />
        </div>
        <Skeleton className="h-3.5 w-12" />
      </div>
      <div className="mt-3 flex gap-1.5">
        {Array.from({ length: 4 }).map((_, i) => (
          <Skeleton key={i} className="h-4 w-14 rounded-full" />
        ))}
      </div>
    </div>
  )
}

function ClientAvatar({ initials }: { initials: string }) {
  return (
    <span
      className="inline-flex h-8 w-8 shrink-0 items-center justify-center rounded-full bg-[var(--color-accent)] text-[11px] font-semibold text-[var(--color-accent-foreground)] ring-2 ring-[var(--color-border)]"
      aria-hidden="true"
    >
      {initials}
    </span>
  )
}

interface QueueCardProps {
  booking: TodayBooking
  emphasizeCheckin?: boolean
  onRefresh?: () => void
}

function QueueCard({ booking, emphasizeCheckin, onRefresh }: QueueCardProps) {
  const [drawerOpen, setDrawerOpen] = useState(false)

  const checkinState = getCheckinState(booking)
  const formsState = getFormsState(booking)
  const depositState = getDepositState(booking)
  const balanceState = getBalanceState(booking)

  function handleCheckin() {
    if (checkinState === 'done') {
      toast.info('Client already checked in')
      return
    }
    // Optimistic toast — the mutation is handled in AppointmentDetailDrawer
    toast.info('Opening booking to check in…')
    setDrawerOpen(true)
  }

  function handleForms() {
    if (formsState === 'done') {
      toast.info('Consent forms already signed')
      return
    }
    toast.info('Opening booking to send form link…')
    setDrawerOpen(true)
  }

  function handleDeposit() {
    if (depositState === 'done') {
      toast.info('Deposit already collected')
      return
    }
    toast.info('Opening booking to collect deposit…')
    setDrawerOpen(true)
  }

  function handleBalance() {
    if (balanceState === 'done') {
      toast.info('Balance already paid')
      return
    }
    toast.info('Opening booking to collect balance…')
    setDrawerOpen(true)
  }

  return (
    <>
      <article
        className={cn(
          'group relative shrink-0 scroll-snap-start rounded-xl border border-[var(--color-border)] bg-[var(--color-card)] p-3 transition-all duration-150',
          'hover:border-[var(--color-primary)]/40 hover:shadow-[var(--shadow-card-hover)]',
          'cursor-pointer focus-visible:outline-none focus-visible:ring-2 focus-visible:ring-[var(--color-ring)] focus-visible:ring-offset-2',
        )}
        style={{ width: 260, minHeight: 110 }}
        role="button"
        tabIndex={0}
        aria-label={`${booking.clientName} — ${booking.serviceName} at ${format(new Date(booking.scheduled_at), 'h:mm a')}`}
        onClick={() => setDrawerOpen(true)}
        onKeyDown={(e) => {
          if (e.key === 'Enter' || e.key === ' ') {
            e.preventDefault()
            setDrawerOpen(true)
          }
        }}
      >
        {/* Top row */}
        <div className="flex items-start gap-2">
          <ClientAvatar initials={booking.clientInitials} />

          <div className="min-w-0 flex-1">
            <p className="truncate text-[13px] font-semibold leading-tight text-[var(--color-foreground)]">
              {truncate(booking.clientName, 20)}
            </p>
            <p className="mt-0.5 truncate text-[11px] text-[var(--color-muted-foreground)]">
              {truncate(booking.serviceName, 22)}
            </p>
            <p className="mt-0.5 truncate text-[10px] text-[var(--color-muted-foreground)]/70">
              {truncate(booking.artistName, 16)}
            </p>
          </div>

          <time
            className="shrink-0 text-[11px] font-medium text-[var(--color-muted-foreground)]"
            dateTime={booking.scheduled_at}
          >
            {format(new Date(booking.scheduled_at), 'h:mm a')}
          </time>
        </div>

        {/* Status chips — stop propagation so chip clicks don't open drawer */}
        <div
          className="mt-2.5 flex flex-wrap gap-1"
          onClick={(e) => e.stopPropagation()}
          onKeyDown={(e) => e.stopPropagation()}
          role="group"
          aria-label="Booking status actions"
        >
          <StatusChip
            label="Check-in"
            state={checkinState}
            onClick={handleCheckin}
            emphasized={emphasizeCheckin && checkinState !== 'done'}
          />
          <StatusChip
            label="Forms"
            state={formsState}
            onClick={handleForms}
          />
          <StatusChip
            label="Deposit"
            state={depositState}
            onClick={handleDeposit}
          />
          <StatusChip
            label="Balance"
            state={balanceState}
            onClick={handleBalance}
          />
        </div>
      </article>

      <AppointmentDetailDrawer
        open={drawerOpen}
        onOpenChange={setDrawerOpen}
        bookingId={booking.id}
        onStatusChange={() => {
          setDrawerOpen(false)
          onRefresh?.()
        }}
      />
    </>
  )
}

export function TodayQueue({
  bookings,
  isLoading,
  emphasizeCheckin,
  onRefresh,
}: TodayQueueProps) {
  const scrollRef = useRef<HTMLDivElement>(null)

  if (isLoading) {
    return (
      <div
        className="flex gap-3 overflow-x-auto pb-1"
        style={{ scrollSnapType: 'x mandatory' }}
        aria-label="Today's queue loading"
        aria-busy="true"
      >
        {Array.from({ length: 4 }).map((_, i) => (
          <QueueCardSkeleton key={i} />
        ))}
      </div>
    )
  }

  if (bookings.length === 0) {
    return (
      <div className="flex h-[110px] items-center justify-center rounded-xl border border-dashed border-[var(--color-border)] bg-[var(--color-muted)]/40">
        <p className="text-sm text-[var(--color-muted-foreground)]">No bookings scheduled today</p>
      </div>
    )
  }

  return (
    <div
      ref={scrollRef}
      className="flex gap-3 overflow-x-auto pb-1 [scrollbar-width:none] [&::-webkit-scrollbar]:hidden"
      style={{ scrollSnapType: 'x mandatory' }}
      role="list"
      aria-label="Today's booking queue"
    >
      {bookings.map((booking) => (
        <div key={booking.id} role="listitem" style={{ scrollSnapAlign: 'start' }}>
          <QueueCard
            booking={booking}
            emphasizeCheckin={emphasizeCheckin}
            onRefresh={onRefresh}
          />
        </div>
      ))}
    </div>
  )
}

'use client'

import { useState } from 'react'
import Link from 'next/link'
import { toast } from 'sonner'
import {
  CreditCard,
  CalendarPlus,
  Heart,
  ShoppingBag,
} from 'lucide-react'
import type { LucideIcon } from 'lucide-react'
import { AppointmentDrawer } from '@/components/appointments/AppointmentDrawer'
