}

'use client'

import { useTodayQueue } from '@/hooks/use-today-queue'
import { TodayQueue } from './TodayQueue'
import { formatCurrency } from '@/lib/utils'
import { cn } from '@/lib/utils'
import { AlertTriangle, CalendarDays, Clock, ShieldAlert } from 'lucide-react'
import type { InventoryAlertsData } from '@/hooks/dashboard/use-inventory-alerts'
import type { TodayBooking } from '@/hooks/use-today-queue'

type StudioRole = 'owner' | 'admin' | 'artist' | 'receptionist' | 'guest_artist'

interface RoleAwareHeroProps {
  role: StudioRole
  studioId: string
  /** Artist's own artist_id — only populated when role === 'artist' or 'guest_artist' */
  ownArtistId?: string | null
  /** Artist earnings today (cents) — pre-fetched server-side for artist/guest_artist roles */
  artistEarningsToday?: number
  /** Inventory alerts data for receptionist role */
  inventoryAlerts?: InventoryAlertsData | null
}

// ─── Shared section header ────────────────────────────────────────────────────

function SectionLabel({ children }: { children: React.ReactNode }) {
  return (
    <h2 className="mb-2 text-[11px] font-semibold uppercase tracking-[0.08em] text-[var(--color-muted-foreground)]">
      {children}
    </h2>
  )
}

// ─── Artist earnings card ─────────────────────────────────────────────────────

function EarningsTodayCard({ earnings }: { earnings: number }) {
  return (
    <div className="rounded-xl border border-[var(--color-border)] bg-[var(--color-card)] p-4 shadow-[var(--shadow-soft)]">
      <p className="text-[11px] font-medium uppercase tracking-[0.08em] text-[var(--color-muted-foreground)]">
        My Earnings Today
      </p>
      <p className="mt-1 text-2xl font-bold tracking-tight text-[var(--color-success-foreground)]">
        {formatCurrency(earnings, 'USD')}
      </p>
      <p className="mt-0.5 text-[11px] text-[var(--color-muted-foreground)]">
        from completed sessions
      </p>
    </div>
  )
}

// ─── Next appointments summary (artist) ──────────────────────────────────────

function NextAppointmentsSummary({ bookings }: { bookings: TodayBooking[] }) {
  const now = new Date()
  const upcoming = bookings
    .filter(
      (b) =>
        new Date(b.scheduled_at) >= now &&
        b.status !== 'cancelled' &&
        b.status !== 'completed',
    )
    .slice(0, 3)

  if (upcoming.length === 0) {
    return (
      <div className="rounded-xl border border-[var(--color-border)] bg-[var(--color-card)] p-4 shadow-[var(--shadow-soft)]">
        <p className="text-[11px] font-medium uppercase tracking-[0.08em] text-[var(--color-muted-foreground)]">
          My Next Appointments
        </p>
        <p className="mt-2 text-sm text-[var(--color-muted-foreground)]">No more appointments today</p>
      </div>
    )
  }

  return (
    <div className="rounded-xl border border-[var(--color-border)] bg-[var(--color-card)] p-4 shadow-[var(--shadow-soft)]">
      <p className="mb-2 text-[11px] font-medium uppercase tracking-[0.08em] text-[var(--color-muted-foreground)]">
        My Next Appointments
      </p>
      <ol className="space-y-2">
        {upcoming.map((b, idx) => (
          <li key={b.id} className="flex items-center gap-2">
            <span className="flex h-5 w-5 shrink-0 items-center justify-center rounded-full bg-[var(--color-accent)] text-[10px] font-semibold text-[var(--color-accent-foreground)]">
              {idx + 1}
            </span>
            <span className="min-w-0 flex-1 truncate text-[12px] font-medium text-[var(--color-foreground)]">
              {b.clientName}
            </span>
            <span className="shrink-0 text-[11px] text-[var(--color-muted-foreground)]">
              {new Date(b.scheduled_at).toLocaleTimeString('en-US', {
                hour: 'numeric',
                minute: '2-digit',
              })}
            </span>
          </li>
        ))}
      </ol>
    </div>
  )
}

// ─── Inventory alert summary (receptionist) ──────────────────────────────────

function InventoryAlertSummary({ alerts }: { alerts: InventoryAlertsData }) {
  const hasCritical = alerts.items_below_threshold.some((i) => i.stock_level === 0)
  const count = alerts.open_alerts_count

  if (count === 0) {
    return (
      <div className="flex items-center gap-2 rounded-xl border border-[var(--color-success)]/30 bg-[var(--color-success-bg)] p-3">
        <div className="flex h-7 w-7 shrink-0 items-center justify-center rounded-lg bg-[var(--color-success)]/20">
          <AlertTriangle className="h-3.5 w-3.5 text-[var(--color-success-foreground)]" aria-hidden="true" />
        </div>
        <p className="text-[12px] font-medium text-[var(--color-success-foreground)]">
          All inventory levels OK
        </p>
      </div>
    )
  }

  return (
    <div
      className={cn(
        'flex items-center gap-2 rounded-xl border p-3',
        hasCritical
          ? 'border-[var(--color-destructive)]/30 bg-[var(--color-destructive)]/10'
          : 'border-[var(--color-warning)]/30 bg-[var(--color-warning-bg)]',
      )}
    >
      <div
        className={cn(
          'flex h-7 w-7 shrink-0 items-center justify-center rounded-lg',
          hasCritical ? 'bg-[var(--color-destructive)]/20' : 'bg-[var(--color-warning)]/20',
        )}
      >
        <AlertTriangle
          className={cn(
            'h-3.5 w-3.5',
            hasCritical ? 'text-[var(--color-destructive)]' : 'text-[var(--color-warning-foreground)]',
          )}
          aria-hidden="true"
        />
      </div>
      <div>
        <p
          className={cn(
            'text-[12px] font-semibold',
            hasCritical ? 'text-[var(--color-destructive)]' : 'text-[var(--color-warning-foreground)]',
          )}
        >
          {count} inventory alert{count !== 1 ? 's' : ''}
        </p>
        <p className="text-[11px] text-[var(--color-muted-foreground)]">
          {hasCritical ? 'Critical: out of stock items' : 'Some items running low'}
        </p>
      </div>
    </div>
  )
}

// ─── Walk-in queue placeholder (receptionist) ────────────────────────────────

function WalkInQueuePlaceholder() {
  return (
    <div className="flex items-center gap-3 rounded-xl border border-dashed border-[var(--color-border)] bg-[var(--color-muted)]/40 p-4">
      <div className="flex h-8 w-8 shrink-0 items-center justify-center rounded-lg bg-[var(--color-accent)]">
        <Clock className="h-4 w-4 text-[var(--color-accent-foreground)]" aria-hidden="true" />
      </div>
      <div>
        <p className="text-[13px] font-semibold text-[var(--color-foreground)]">Walk-in Queue</p>
        <p className="text-[11px] text-[var(--color-muted-foreground)]">
          Walk-in management coming in next sprint
        </p>
      </div>
    </div>
  )
}

// ─── Guest artist access notice ───────────────────────────────────────────────

function GuestArtistNotice() {
  return (
    <div className="flex items-start gap-3 rounded-xl border border-[var(--color-warning)]/30 bg-[var(--color-warning-bg)] p-3">
      <ShieldAlert className="mt-0.5 h-4 w-4 shrink-0 text-[var(--color-warning-foreground)]" aria-hidden="true" />
      <div>
        <p className="text-[12px] font-semibold text-[var(--color-warning-foreground)]">
          Guest artist access
        </p>
        <p className="mt-0.5 text-[11px] text-[var(--color-warning-foreground)]/80">
          You can view your own sessions. Studio-wide data is restricted.
        </p>
      </div>
    </div>
  )
}

// ─── Residency info card (guest_artist) ──────────────────────────────────────

function ResidencyCard() {
  return (
    <div className="rounded-xl border border-[var(--color-border)] bg-[var(--color-card)] p-4 shadow-[var(--shadow-soft)]">
      <div className="flex items-center gap-2">
        <CalendarDays className="h-4 w-4 text-[var(--color-primary)]" aria-hidden="true" />
        <p className="text-[13px] font-semibold text-[var(--color-foreground)]">My Residency</p>
      </div>
      <p className="mt-1.5 text-[12px] text-[var(--color-muted-foreground)]">
        Residency dates and commission summary are available in your guest artist profile.
      </p>
    </div>
  )
}

// ─── Role hero variants ───────────────────────────────────────────────────────

function OwnerHero({ studioId }: { studioId: string }) {
  const queueQuery = useTodayQueue(true)
  return (
    <div className="space-y-3">
      <SectionLabel>Today&apos;s Queue</SectionLabel>
      <TodayQueue
        bookings={queueQuery.data ?? []}
        isLoading={queueQuery.isLoading}
        onRefresh={() => void queueQuery.refetch()}
      />
    </div>
  )
}

function ArtistHero({
  ownArtistId,
  artistEarningsToday,
}: {
  ownArtistId: string | null | undefined
  artistEarningsToday: number
}) {
  const queueQuery = useTodayQueue(true, ownArtistId ?? undefined)
  const bookings = queueQuery.data ?? []

  return (
    <div className="space-y-3">
      <SectionLabel>My Chair Today</SectionLabel>
      <TodayQueue
        bookings={bookings}
        isLoading={queueQuery.isLoading}
        onRefresh={() => void queueQuery.refetch()}
      />
      <div className="grid grid-cols-1 gap-3 sm:grid-cols-2">
        <EarningsTodayCard earnings={artistEarningsToday} />
        <NextAppointmentsSummary bookings={bookings} />
      </div>
    </div>
  )
}

function ReceptionistHero({ inventoryAlerts }: { inventoryAlerts: InventoryAlertsData | null | undefined }) {
  const queueQuery = useTodayQueue(true)
  return (
    <div className="space-y-3">
      <SectionLabel>Today&apos;s Queue</SectionLabel>
      <TodayQueue
        bookings={queueQuery.data ?? []}
        isLoading={queueQuery.isLoading}
        emphasizeCheckin
        onRefresh={() => void queueQuery.refetch()}
      />
      {inventoryAlerts && <InventoryAlertSummary alerts={inventoryAlerts} />}
      <WalkInQueuePlaceholder />
    </div>
  )
}

function GuestArtistHero({
  ownArtistId,
  artistEarningsToday,
}: {
  ownArtistId: string | null | undefined
  artistEarningsToday: number
}) {
  const queueQuery = useTodayQueue(true, ownArtistId ?? undefined)

  return (
    <div className="space-y-3">
      <SectionLabel>My Sessions Today</SectionLabel>
      <TodayQueue
        bookings={queueQuery.data ?? []}
        isLoading={queueQuery.isLoading}
        onRefresh={() => void queueQuery.refetch()}
      />
      <div className="grid grid-cols-1 gap-3 sm:grid-cols-2">
        <ResidencyCard />
        <EarningsTodayCard earnings={artistEarningsToday} />
      </div>
      <GuestArtistNotice />
    </div>
  )
}

// ─── Main export ─────────────────────────────────────────────────────────────

export function RoleAwareHero({
  role,
  studioId,
  ownArtistId,
  artistEarningsToday = 0,
  inventoryAlerts,
}: RoleAwareHeroProps) {
  if (role === 'artist') {
    return (
      <ArtistHero
        ownArtistId={ownArtistId}
        artistEarningsToday={artistEarningsToday}
      />
    )
  }

  if (role === 'receptionist') {
    return <ReceptionistHero inventoryAlerts={inventoryAlerts} />
  }

  if (role === 'guest_artist') {
    return (
      <GuestArtistHero
        ownArtistId={ownArtistId}
        artistEarningsToday={artistEarningsToday}
      />
    )
  }

  // owner | admin
  return <OwnerHero studioId={studioId} />
}

